using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Unity.Profiling;using UnityEngine.Rendering;using IslandGame;using IslandGame.Diorama;using Newtonsoft.Json.Linq;
public static class MeasurePreview {
 const string Dir="C:/Users/SHK/island-contact-diorama-20261107/evidence/";
 public static object Main(){IslandGame.Editor.BattleHudReview.SetSize(1080,1920);var window=EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView"));window.Focus();Application.runInBackground=true;EditorApplication.isPaused=false;var stage=UnityEngine.Object.FindFirstObjectByType<DioramaPreviewStage>();stage.StartCoroutine(Run(stage,window));return new{started=true,expectedSeconds=135};}
 static IEnumerator Run(DioramaPreviewStage stage,EditorWindow window){var pipeline=GraphicsSettings.defaultRenderPipeline;var results=new JArray();var errors=new List<string>();Application.LogCallback callback=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception)errors.Add(m);};Application.logMessageReceived+=callback;stage.GetComponent<DioramaPreviewControls>().visible=false;stage.bloom=stage.depthOfField=stage.vignette=stage.outline=stage.rim=false;
  foreach(DioramaSurface surface in Enum.GetValues(typeof(DioramaSurface))){stage.RestoreMaterials();GraphicsSettings.defaultRenderPipeline=surface==DioramaSurface.BuiltInBaseline?null:pipeline;QualitySettings.renderPipeline=GraphicsSettings.defaultRenderPipeline;stage.surface=surface;
   foreach(DioramaView shot in Enum.GetValues(typeof(DioramaView))){stage.shot=shot;stage.animate=false;stage.ResetSample();stage.RefreshLook();double warm=Time.realtimeSinceStartupAsDouble;while(Time.realtimeSinceStartupAsDouble-warm<5){window.Repaint();yield return null;}
    // Reset only the diagnostic adaptive-quality state so all candidates start at full quality.
    typeof(IslandBudgetPolicy).GetProperty("Level").SetValue(IslandFrameBudget.Current.Policy,0);stage.animate=true;stage.ResetSample();var rows=new List<double[]>(700);var gc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");double start=Time.realtimeSinceStartupAsDouble,previous=start;int lowestQuality=0;
    while(Time.realtimeSinceStartupAsDouble-start<10){window.Repaint();yield return null;double now=Time.realtimeSinceStartupAsDouble;var budget=IslandFrameBudget.Current;rows.Add(new[]{(now-previous)*1000,budget.CpuActiveMilliseconds,budget.GpuMilliseconds,gc.Valid?(double)gc.LastValue:-1,UnityStats.drawCalls,UnityStats.setPassCalls});previous=now;lowestQuality=Math.Max(lowestQuality,budget.Policy.Level);}
    gc.Dispose();results.Add(new JObject{["view"]=shot.ToString(),["surface"]=surface.ToString(),["seconds"]=10,["samples"]=rows.Count,["frameMs"]=Stats(rows.Select(r=>r[0])),["cpuActiveMs"]=Stats(rows.Select(r=>r[1])),["gpuDiagnosticMs"]=Stats(rows.Select(r=>r[2])),["gcBytes"]=Stats(rows.Select(r=>r[3])),["drawCalls"]=Stats(rows.Select(r=>r[4])),["setPass"]=Stats(rows.Select(r=>r[5])),["usedBytes"]=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),["reservedBytes"]=UnityEngine.Profiling.Profiler.GetTotalReservedMemoryLong(),["maxAdaptiveQualityLevel"]=lowestQuality});
    File.WriteAllText(Dir+"preview-cost-progress.json",results.ToString());
   }
  }
  stage.animate=false;GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;stage.surface=DioramaSurface.UrpLit;stage.RefreshLook();stage.GetComponent<DioramaPreviewControls>().visible=true;Application.logMessageReceived-=callback;
  File.WriteAllText(Dir+"preview-cost.json",new JObject{["editor"]=true,["resolution"]="1080x1920",["postEffects"]=false,["deviceTest"]="Deferred by user; Unity verification requested",["gpuCaveat"]="Editor diagnostic timing only; not Android GPU certification",["runs"]=results,["errors"]=new JArray(errors)}.ToString());
 }
 static JObject Stats(IEnumerable<double> values){var a=values.OrderBy(x=>x).ToArray();return new JObject{["mean"]=a.Average(),["p95"]=a[(int)((a.Length-1)*.95)],["p99"]=a[(int)((a.Length-1)*.99)],["max"]=a.Last()};}
}
